"""mytoml: a hand-written parser for a subset of TOML.

Supported: bare/dotted keys, basic strings (with escapes), literal strings,
integers (signs, underscores), floats, booleans, arrays (nested, mixed,
trailing commas), [table] / [dotted.table] headers, comments, and
TomlError with line numbers for duplicate keys, redefined tables, and
unterminated strings.
"""


class TomlError(Exception):
    """Parse error carrying a 1-indexed line number."""

    def __init__(self, message, line):
        super().__init__(f"line {line}: {message}")
        self.message = message
        self.line = line


_BARE = set(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
)
_NUM = set("0123456789+-_.eE")
_HEX = set("0123456789abcdefABCDEF")
_ESCAPES = {
    "b": "\b",
    "t": "\t",
    "n": "\n",
    "f": "\f",
    "r": "\r",
    '"': '"',
    "\\": "\\",
}


class _Parser:
    def __init__(self, text):
        if isinstance(text, bytes):
            text = text.decode("utf-8")
        self.t = text
        self.n = len(text)
        self.i = 0
        self.root = {}
        self.cur = self.root
        self.explicit_tables = set()

    # ------------------------------------------------------------- low level

    def err(self, msg, pos=None):
        pos = self.i if pos is None else pos
        raise TomlError(msg, self.t.count("\n", 0, pos) + 1)

    def peek(self):
        return self.t[self.i] if self.i < self.n else ""

    def skip_ws(self):
        while self.peek() in (" ", "\t"):
            self.i += 1

    def skip_comment(self):
        if self.peek() == "#":
            while self.peek() not in ("", "\n"):
                self.i += 1

    def skip_blank(self):
        """Skip spaces, tabs, newlines and full comment lines."""
        while True:
            c = self.peek()
            if c in (" ", "\t", "\r", "\n"):
                self.i += 1
            elif c == "#":
                self.skip_comment()
            else:
                return

    def end_of_line(self):
        self.skip_ws()
        self.skip_comment()
        c = self.peek()
        if c in ("", "\n"):
            return
        if c == "\r":
            self.i += 1
            return
        self.err("expected end of line")

    # ------------------------------------------------------------------ keys

    def single_key(self):
        start = self.i
        while self.peek() in _BARE:
            self.i += 1
        if self.i == start:
            self.err("expected a bare key")
        return self.t[start : self.i]

    def key_path(self):
        parts = []
        while True:
            self.skip_ws()
            parts.append(self.single_key())
            self.skip_ws()
            if self.peek() == ".":
                self.i += 1
                continue
            return parts

    # --------------------------------------------------------------- values

    def value(self):
        c = self.peek()
        if c == '"':
            return self.basic_string()
        if c == "'":
            return self.literal_string()
        if c == "[":
            return self.array()
        if self.t.startswith("true", self.i):
            self.i += 4
            return True
        if self.t.startswith("false", self.i):
            self.i += 5
            return False
        return self.number()

    def basic_string(self):
        open_pos = self.i
        self.i += 1
        out = []
        while True:
            c = self.peek()
            if c in ("", "\n", "\r"):
                self.err("unterminated string", open_pos)
            if c == '"':
                self.i += 1
                return "".join(out)
            if c == "\\":
                self.i += 1
                e = self.peek()
                if e in _ESCAPES:
                    out.append(_ESCAPES[e])
                    self.i += 1
                elif e in ("u", "U"):
                    width = 4 if e == "u" else 8
                    hexpart = self.t[self.i + 1 : self.i + 1 + width]
                    if len(hexpart) < width or any(h not in _HEX for h in hexpart):
                        self.err("invalid unicode escape")
                    out.append(chr(int(hexpart, 16)))
                    self.i += 1 + width
                else:
                    self.err("invalid escape sequence")
            else:
                out.append(c)
                self.i += 1

    def literal_string(self):
        open_pos = self.i
        self.i += 1
        start = self.i
        while True:
            c = self.peek()
            if c in ("", "\n", "\r"):
                self.err("unterminated string", open_pos)
            if c == "'":
                s = self.t[start : self.i]
                self.i += 1
                return s
            self.i += 1

    def array(self):
        arr = []
        self.i += 1
        while True:
            self.skip_blank()
            c = self.peek()
            if c == "]":
                self.i += 1
                return arr
            if c == "":
                self.err("unterminated array")
            arr.append(self.value())
            self.skip_blank()
            c = self.peek()
            if c == ",":
                self.i += 1
                continue
            if c == "]":
                self.i += 1
                return arr
            self.err("expected ',' or ']' in array")

    def number(self):
        start = self.i
        while self.peek() in _NUM:
            self.i += 1
        raw = self.t[start : self.i]
        if not raw:
            self.err("invalid value")
        cleaned = raw.replace("_", "")
        try:
            return int(cleaned, 10)
        except ValueError:
            pass
        try:
            return float(cleaned)
        except ValueError:
            self.err(f"invalid number '{raw}'", start)

    # ------------------------------------------------------------ statements

    def table_header(self):
        start = self.i
        self.i += 1  # consume '['
        if self.peek() == "[":
            self.err("array-of-tables is not supported", start)
        parts = self.key_path()
        self.skip_ws()
        if self.peek() != "]":
            self.err("expected ']' to close table header")
        self.i += 1
        self.end_of_line()

        path = tuple(parts)
        node = self.root
        for p in path[:-1]:
            nxt = node.get(p)
            if nxt is None:
                nxt = node[p] = {}
            if not isinstance(nxt, dict):
                self.err(f"key '{p}' is not a table", start)
            node = nxt
        last = path[-1]
        existing = node.get(last)
        if path in self.explicit_tables:
            self.err(f"redefined table '{'.'.join(path)}'", start)
        if existing is not None and not isinstance(existing, dict):
            self.err(f"table '{'.'.join(path)}' conflicts with a value", start)
        if existing is None:
            node[last] = {}
        self.explicit_tables.add(path)
        self.cur = node[last]

    def key_value(self, table):
        stmt_start = self.i
        parts = self.key_path()
        self.skip_ws()
        if self.peek() != "=":
            self.err("expected '=' after key")
        self.i += 1
        self.skip_ws()
        val = self.value()
        self.end_of_line()

        node = table
        for p in parts[:-1]:
            nxt = node.get(p)
            if nxt is None:
                nxt = node[p] = {}
            if not isinstance(nxt, dict):
                self.err(f"cannot extend non-table key '{p}'", stmt_start)
            node = nxt
        last = parts[-1]
        if last in node:
            self.err(f"duplicate key '{last}'", stmt_start)
        node[last] = val

    # -------------------------------------------------------------- document

    def parse(self):
        while True:
            self.skip_blank()
            if self.i >= self.n:
                break
            if self.peek() == "[":
                self.table_header()
            else:
                self.key_value(self.cur)
        return self.root


def parse(text):
    """Parse a TOML-subset document and return it as a dict."""
    return _Parser(text).parse()

