cd /workspace && python3 - <<'EOF'
import tomllib
from test_mytoml import gen_document
from mytoml import parse, TomlError

def se(a,b):
    if type(a) is not type(b): return False
    if isinstance(a,dict): return a.keys()==b.keys() and all(se(a[k],b[k]) for k in a)
    if isinstance(a,list): return len(a)==len(b) and all(se(x,y) for x,y in zip(a,b))
    return a==b

bad=0
for s in range(100, 2100):
    text, expected = gen_document(s)
    assert se(tomllib.loads(text), expected), f"invalid gen doc seed {s}"
    try:
        got = parse(text)
    except TomlError as e:
        print("parser error", s, e); bad+=1; continue
    if not se(got, expected):
        print("divergence", s); bad+=1
print("done, divergences:", bad)
